import * as BunServices from "@effect/platform-bun/BunServices";
import { expect, it as test } from "@effect/vitest";
import { Crypto, Effect, FileSystem, PlatformError, Result, Schema } from "effect";

import { readDeploymentJson, readDeploymentSha256 } from "./input.boundary.js";

const KnownReceipt = Schema.Struct({ name: Schema.Literal("retained") });

test.effect.each([
  { source: "", expected: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855" },
  { source: "abc", expected: "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad" },
  { source: "TaxKit — café", expected: "7eb898ae9c8bbbcf6a419b3ef8dee5003bd23de0968f4fb1eb12aa9d836c6f27" },
])("preserves SHA-256 for retained $source bytes", ({ source, expected }) =>
  Effect.gen(function* () {
    const fileSystem = yield* FileSystem.FileSystem;
    const root = yield* fileSystem.makeTempDirectoryScoped({ prefix: "taxkit-deployment-input-" });
    yield* fileSystem.writeFileString(`${root}/source.txt`, source);
    expect(yield* readDeploymentSha256(root, "source.txt")).toBe(expected);
  }).pipe(Effect.scoped, Effect.provide(BunServices.layer))
);

test.effect("restores the receipt once at the file boundary", () =>
  Effect.gen(function* () {
    const fileSystem = yield* FileSystem.FileSystem;
    const root = yield* fileSystem.makeTempDirectoryScoped({ prefix: "taxkit-deployment-input-" });
    yield* fileSystem.writeFileString(`${root}/receipt.json`, '{"name":"retained"}');
    expect(yield* readDeploymentJson(root, "receipt.json", KnownReceipt)).toEqual({ name: "retained" });
